args<-commandArgs(TRUE);o<-if(length(args))args[1]else'.';td<-file.path(o,'supplementary_tables');read<-function(n)read.csv(file.path(td,n));d<-read('S17_continuous_donor_example.csv');sl<-read('S16_continuous_slope_recovery.csv');et<-read('S18_eqtl_before_after.csv');summary<-read('S6_standard_comparison.csv')
source(file.path(o,'cell_type_labels.R'))
fig<-function(name,w,h,fun){for(ext in c('pdf','png')){f<-file.path(o,'figures',paste0(name,'.',ext));if(ext=='pdf')pdf(f,width=w,height=h,useDingbats=FALSE)else png(f,width=w,height=h,units='in',res=300,type='cairo');par(mar=c(4.6,4.8,3.1,1),mgp=c(2.8,.8,0),las=1,cex=.94);fun();dev.off()}}
label<-function(x)mtext(x,3,line=1.4,adj=-.11,font=2,cex=1.25)
fig('Figure_3_continuous_examples',10,4.7,function(){par(mfrow=c(1,2));xx<-seq(min(d$phenotype_SD),max(d$phenotype_SD),length.out=150);fit<-lm(estimated_expression~phenotype_SD,d);ref<-lm(reference_expression~phenotype_SD,d);ci<-predict(fit,data.frame(phenotype_SD=xx),interval='confidence');ylim<-range(d$estimated_expression,d$reference_expression,ci);ylim[2]<-ylim[2]+.45;plot(d$phenotype_SD,d$estimated_expression,type='n',ylim=ylim,xlab='Continuous phenotype (SD units)',ylab=paste(d$gene[1],'expression: log2(CPM + 0.5)'),main='Donor-level association');label('A');polygon(c(xx,rev(xx)),c(ci[,2],rev(ci[,3])),col=adjustcolor('#0072B2',.14),border=NA);points(d$phenotype_SD,d$reference_expression,pch=1,col='#888888',cex=.65);points(d$phenotype_SD,d$estimated_expression,pch=16,col=adjustcolor('#0072B2',.75),cex=.8);lines(xx,ci[,1],col='#0072B2',lwd=2);abline(ref,col='#777777',lty=2,lwd=1.6);legend('topleft',c(sprintf('CDSeq2 slope = %.2f',coef(fit)[2]),sprintf('Observed slope = %.2f',coef(ref)[2]),'Band: 95% CI for mean'),col=c('#0072B2','#777777',NA),lty=c(1,2,NA),bty='n',cex=.78);mtext('Excitatory neurons | h = 0.50 | 39 donors',3,line=.2,cex=.73,col='#555555')
 lim<-range(sl$reference_slope,sl$estimated_slope,finite=TRUE)*1.05;plot(sl$reference_slope,sl$estimated_slope,xlim=lim,ylim=lim,pch=16,cex=.43,col=adjustcolor('#999999',.35),xlab='Observed-component association slope',ylab='CDSeq2 association slope',main='Association-effect recovery');label('B');mtext('39-donor sensitivity analysis | fixed selection',3,line=.20,cex=.70,col='#555555');abline(0,1,lty=2,lwd=1.5,col='#555555');points(sl$reference_slope[sl$selected],sl$estimated_slope[sl$selected],pch=16,cex=.52,col=adjustcolor('#0072B2',.6));legend('topleft',c('CDSeq2 (without gene-type prioritization)','CDSeq2 (with gene-type prioritization): top 20%','Equality'),col=c('#999999','#0072B2','#555555'),pch=c(16,16,NA),lty=c(NA,NA,2),bty='n',cex=.68);text(lim[2],lim[1],sprintf('Slope concordance r\nAll: %.3f | selected: %.3f',cor(sl$reference_slope,sl$estimated_slope),cor(sl$reference_slope[sl$selected],sl$estimated_slope[sl$selected])),adj=c(1,0),cex=.8)
})
# Standard BayesPrism has native input preprocessing and no output selection.
maxy<-ceiling(max(-log10(pmax(et$q,1e-300)),na.rm=TRUE))
workflows<-c('BayesPrism standard','CDSeq2 before','CDSeq2 GAM6');wc<-c('#D55E00','#777777','#0072B2')
eq_label<-function(x)mtext(x,3,line=1.3,adj=if(diff(par('fig')[1:2])>.75)-.04 else -.11,font=2,cex=1.25)
eqplot<-function(strength,name){fig(name,10,10,function(){layout(rbind(c(1,1),c(2,2),c(3,3),c(4,5)),heights=c(1,1,1,1.2));par(mar=c(3.6,4.8,2.7,1),cex=.95);idx<-0
for(w in workflows){idx<-idx+1;eng<-if(w=='BayesPrism standard')'BayesPrism'else'CDSeq2';z<-subset(et,engine==eng&signal_ratio==strength);kept<-if(w=='CDSeq2 GAM6')z$selected else rep(TRUE,nrow(z));yy<--log10(pmax(z$q,1e-300));plot(NA,xlim=c(1,762),ylim=c(0,maxy),xaxt='n',xlab='Synthetic variant index within repetition',ylab=expression(-log[10](q[BH])),main=c('BayesPrism | specified input QC; no output selection','CDSeq2 (without gene-type prioritization)','CDSeq2 (with gene-type prioritization) | top 40%')[idx],cex.main=.98);eq_label(LETTERS[idx]);axis(1,c(1,254,255,508,509,762),c('1','254','1','254','1','254'),cex.axis=.75);abline(v=c(254.5,508.5),col='#DDDDDD');abline(h=-log10(.05),lty=2,col='#777777');for(rep in 1:3)text((rep-.5)*254,maxy*.95,paste('Rep',rep),cex=.72,col='#555555')
points(z$display_index[!kept],yy[!kept],pch=16,col='#EEEEEE',cex=.4);ok<-kept&is.finite(yy);points(z$display_index[ok],yy[ok],pch=16,col=ifelse(z$injected[ok],'#75ACCB','#B7B7B7'),cex=.5);missing<-kept&!is.finite(yy);points(z$display_index[missing],rep(0,sum(missing)),pch=4,col='#8B5C98',cex=.8);call<-kept&z$called;points(z$display_index[call],yy[call],pch=1,col=ifelse(z$correct_detection[call],'#0072B2','#CC3311'),cex=.78);fdp<-sum(call&!z$injected)/sum(call);legend('topright',sprintf('FDP %.1f%% | %d calls | %d false',100*fdp,sum(call),sum(call&!z$injected)),bty='n',cex=.76,inset=c(0,.12))}
par(mar=c(6,4.8,3.1,1));z<-subset(summary,signal_ratio>0);mat<-sapply(c(.5,.8),function(h){q<-subset(z,signal_ratio==h);q$pooled_FDP[match(workflows,q$workflow)]*100});xx<-barplot(mat,beside=TRUE,col=wc,border=NA,names.arg=c('0.5','0.8'),ylim=c(0,max(80,ceiling(max(mat)/10)*10+35)),ylab='Pooled FDP (%)',xlab='Standardized injected eQTL effect size',main='False-discovery proportions');eq_label('D');text(xx,mat+2,sprintf('%.1f',mat),cex=.76);legend('topleft',c('BayesPrism','CDSeq2 (without gene-type prioritization)','CDSeq2 (with gene-type prioritization)'),fill=wc,bty='n',cex=.70)
z<-subset(summary,signal_ratio==strength);z<-z[match(workflows,z$workflow),];v<-z$correct_detected;xx<-barplot(v,col=wc,border=NA,names.arg=rep('',3),ylim=c(0,max(v)*1.3),ylab='Correct discoveries',main=paste('Discovery coverage | effect size',strength),cex.names=.65);axis(1,at=xx,labels=c('BayesPrism','CDSeq2\n(without gene-type\nprioritization)','CDSeq2\n(with gene-type\nprioritization)'),tick=FALSE,line=1.1,cex.axis=.65);eq_label('E');text(xx,v+max(v)*.045,v,cex=.86);mtext('Counts across all three repetitions',1,line=4.4,cex=.70)
})}
eqplot(.5,'Figure_4_eqtl_before_after');eqplot(.8,'Figure_S8_eqtl_before_after_strong')
